import com.beeproof.domain.Beekeeper;
import com.beeproof.domain.Role;
import com.beeproof.domain.User;
import com.beeproof.dto.LoginRequest;
import com.beeproof.dto.LoginResponse;
import com.beeproof.dto.UserDto;
import com.beeproof.repository.BeekeeperRepository;
import com.beeproof.repository.UserRepository;
import com.beeproof.security.JwtTokenProvider;
import com.beeproof.security.UserPrincipal;
import lombok.RequiredArgsConstructor;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class AuthService {

    private final AuthenticationManager authenticationManager;
    private final JwtTokenProvider tokenProvider;
    private final UserRepository userRepository;
    private final BeekeeperRepository beekeeperRepository;
    private final AuditService auditService;

    @Transactional
    public LoginResponse login(LoginRequest request) {
        Authentication authentication = authenticationManager.authenticate(
                new UsernamePasswordAuthenticationToken(request.getUsername(), request.getPassword())
        );

        SecurityContextHolder.getContext().setAuthentication(authentication);
        String jwt = tokenProvider.generateToken(authentication);

        UserPrincipal principal = (UserPrincipal) authentication.getPrincipal();
        User user = userRepository.findById(principal.getId())
                .orElseThrow(() -> new IllegalStateException("Authenticated user not found"));

        UserDto userDto = buildUserDto(user);

        auditService.log("USER_LOGIN", "User", user.getId().toString(), user.getUsername(), "Successful login via credentials");

        return LoginResponse.builder()
                .token(jwt)
                .type("Bearer")
                .user(userDto)
                .build();
    }

    @Transactional(readOnly = true)
    public UserDto getCurrentUser(String username) {
        User user = userRepository.findByUsername(username)
                .or(() -> userRepository.findByEmail(username))
                .orElseThrow(() -> new IllegalStateException("User not found: " + username));
        return buildUserDto(user);
    }

    private UserDto buildUserDto(User user) {
        Set<String> roleNames = user.getRoles().stream()
                .map(r -> r.getName().name())
                .collect(Collectors.toSet());

        String primaryRole = roleNames.stream().findFirst().orElse("USER");

        String kvicReg = null;
        String clusterName = null;

        Optional<Beekeeper> beekeeperOpt = beekeeperRepository.findByUser(user);
        if (beekeeperOpt.isPresent()) {
            Beekeeper b = beekeeperOpt.get();
            kvicReg = b.getKvicRegistrationNumber();
            if (b.getAssignedCluster() != null) {
                clusterName = b.getAssignedCluster().getName();
            }
        }

        return UserDto.builder()
                .id(user.getId())
                .username(user.getUsername())
                .email(user.getEmail())
                .fullName(user.getFullName())
                .phoneNumber(user.getPhoneNumber())
                .roles(roleNames)
                .primaryRole(primaryRole)
                .kvicRegistrationNumber(kvicReg)
                .assignedClusterName(clusterName)
                .build();
    }
}

package com.beeproof.service;

import com.beeproof.domain.*;
import com.beeproof.dto.BatchVerificationResponse;
import com.beeproof.exception.ResourceNotFoundException;
import com.beeproof.repository.CommonRepositories.*;
import com.beeproof.repository.HoneyBatchRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

@Service
@RequiredArgsConstructor
public class VerificationService {

    private final HoneyBatchRepository batchRepository;
    private final QualityReportRepository qualityReportRepository;
    private final HarvestEventRepository harvestEventRepository;
    private final ProcessingEventRepository processingEventRepository;
    private final DistributionEventRepository distributionEventRepository;
    private final AuditService auditService;

    @Transactional
    public BatchVerificationResponse verifyBatch(String batchNumber) {
        HoneyBatch batch = batchRepository.findByBatchNumber(batchNumber.trim().toUpperCase())
                .orElseThrow(() -> new ResourceNotFoundException("Batch not found with identifier: " + batchNumber));

        Cluster cluster = batch.getCluster();
        Optional<QualityReport> qualityReportOpt = qualityReportRepository.findByBatch(batch);

        BatchVerificationResponse.QualitySummary qualitySummary = null;
        if (qualityReportOpt.isPresent()) {
            QualityReport qr = qualityReportOpt.get();
            qualitySummary = BatchVerificationResponse.QualitySummary.builder()
                    .certificateNumber(qr.getCertificateNumber())
                    .laboratoryName(qr.getLaboratoryName())
                    .moisturePercentage(qr.getMoisturePercentage())
                    .pollenPurityScore(qr.getPollenPurityScore())
                    .nmrSpectroscopyPassed(qr.getNmrSpectroscopyPassed())
                    .c4SugarAdulterationDetected(qr.getC4SugarAdulterationDetected())
                    .verdict(qr.getOverallVerdict())
                    .certifiedAt(qr.getCertifiedAt())
                    .build();
        }

        // Build provenance timeline
        List<BatchVerificationResponse.ProvenanceEvent> timeline = new ArrayList<>();

        // 1. Harvest Stage
        timeline.add(BatchVerificationResponse.ProvenanceEvent.builder()
                .stage("HARVEST")
                .title("Apiary Harvest Logged")
                .actor("Certified KVIC Beekeepers")
                .location(cluster.getName() + ", " + cluster.getState())
                .timestamp(batch.getHarvestDate().atTime(8, 30))
                .details("Raw unadulterated comb honey harvested from " + cluster.getPredominantFlora() + " flora.")
                .completed(true)
                .build());

        // 2. Processing Stage
        List<ProcessingEvent> processingEvents = processingEventRepository.findByBatch(batch);
        boolean processingDone = !processingEvents.isEmpty();
        timeline.add(BatchVerificationResponse.ProvenanceEvent.builder()
                .stage("PROCESSING")
                .title("Standard Cold Filtration & Normalization")
                .actor(processingDone ? processingEvents.get(0).getFacilityName() : "Regional Processing Plant")
                .location(cluster.getState())
                .timestamp(processingDone ? processingEvents.get(0).getProcessedAt() : batch.getCreatedAt().plusDays(2))
                .details("Filtered at <40°C preserving native enzymes, diastase, and invertase vitality.")
                .completed(processingDone)
                .build());

        // 3. Laboratory Testing Stage
        boolean labDone = qualityReportOpt.isPresent();
        timeline.add(BatchVerificationResponse.ProvenanceEvent.builder()
                .stage("TESTING")
                .title("Laboratory Nuclear Magnetic Resonance (NMR) & Purity Assay")
                .actor(labDone ? qualityReportOpt.get().getLaboratoryName() : "Accredited NABL Testing Lab")
                .location("National Food Quality Laboratory")
                .timestamp(labDone ? qualityReportOpt.get().getCertifiedAt() : batch.getCreatedAt().plusDays(4))
                .details(labDone ? "Certificate #" + qualityReportOpt.get().getCertificateNumber() + " - " + qualityReportOpt.get().getOverallVerdict() : "Pending final laboratory assay")
                .completed(labDone)
                .build());

        // 4. Packaging & Dispatch Stage
        List<DistributionEvent> distributionEvents = distributionEventRepository.findByBatch(batch);
        boolean distDone = !distributionEvents.isEmpty();
        timeline.add(BatchVerificationResponse.ProvenanceEvent.builder()
                .stage("DISTRIBUTION")
                .title("Tamper-Evident Packaging & Custody Handover")
                .actor(distDone ? distributionEvents.get(0).getDistributor().getFullName() : "Authorized Distributor")
                .location(distDone ? distributionEvents.get(0).getDestinationLocation() : "Supply Chain Network")
                .timestamp(distDone ? distributionEvents.get(0).getEventTimestamp() : batch.getCreatedAt().plusDays(6))
                .details("Sealed with cryptographic serial codes for consumer end-to-end provenance verification.")
                .completed(distDone)
                .build());

        auditService.log("PUBLIC_BATCH_VERIFIED", "HoneyBatch", batch.getBatchNumber(), "ANONYMOUS_CONSUMER", "Public provenance lookup for " + batch.getBatchNumber());

        return BatchVerificationResponse.builder()
                .batchNumber(batch.getBatchNumber())
                .verificationStatus("Provenance Verified")
                .status(batch.getStatus().name())
                .harvestDate(batch.getHarvestDate())
                .floralSource(batch.getFloralSource())
                .totalQuantityKg(batch.getTotalQuantityKg())
                .blockchainTxHash(batch.getBlockchainTxHash())
                .clusterCode(cluster.getClusterCode())
                .clusterName(cluster.getName())
                .region(cluster.getRegion())
                .state(cluster.getState())
                .district(cluster.getDistrict())
                .latitude(cluster.getLatitude())
                .longitude(cluster.getLongitude())
                .qualitySummary(qualitySummary)
                .timeline(timeline)
                .build();
    }
}

package com.beeproof.service;

import com.beeproof.domain.*;
import com.beeproof.dto.DomainDtos.*;
import com.beeproof.repository.*;
import com.beeproof.repository.CommonRepositories.AuditLogRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class AdminService {

    private final UserRepository userRepository;
    private final BeekeeperRepository beekeeperRepository;
    private final ClusterRepository clusterRepository;
    private final HiveRepository hiveRepository;
    private final HoneyBatchRepository batchRepository;
    private final AuditLogRepository auditLogRepository;

    @Transactional(readOnly = true)
    public AdminOverviewResponse getOverview() {
        long totalUsers = userRepository.count();
        long totalBeekeepers = beekeeperRepository.count();
        long totalClusters = clusterRepository.count();
        long totalHives = hiveRepository.count();
        long totalHoneyBatches = batchRepository.count();

        List<ClusterDto> clusters = getAllClusters();
        List<BeekeeperDto> recentBeekeepers = getAllBeekeepers().stream().limit(5).collect(Collectors.toList());
        List<AuditLogDto> recentAuditLogs = getAuditLogs().stream().limit(10).collect(Collectors.toList());

        return AdminOverviewResponse.builder()
                .totalUsers(totalUsers)
                .totalBeekeepers(totalBeekeepers)
                .totalClusters(totalClusters)
                .totalHives(totalHives)
                .totalHoneyBatches(totalHoneyBatches)
                .totalVerifiedBatches(totalHoneyBatches)
                .clusters(clusters)
                .recentBeekeepers(recentBeekeepers)
                .recentAuditLogs(recentAuditLogs)
                .build();
    }

    @Transactional(readOnly = true)
    public List<ClusterDto> getAllClusters() {
        return clusterRepository.findAll().stream().map(c -> {
            long hiveCount = hiveRepository.findByCluster(c).size();
            long beekeeperCount = beekeeperRepository.findByAssignedCluster(c).size();
            return ClusterDto.builder()
                    .id(c.getId())
                    .clusterCode(c.getClusterCode())
                    .name(c.getName())
                    .region(c.getRegion())
                    .state(c.getState())
                    .district(c.getDistrict())
                    .predominantFlora(c.getPredominantFlora())
                    .latitude(c.getLatitude())
                    .longitude(c.getLongitude())
                    .hiveCount(hiveCount)
                    .beekeeperCount(beekeeperCount)
                    .build();
        }).collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<BeekeeperDto> getAllBeekeepers() {
        return beekeeperRepository.findAll().stream().map(b -> {
            long hiveCount = hiveRepository.countByBeekeeper(b);
            return BeekeeperDto.builder()
                    .id(b.getId())
                    .fullName(b.getUser().getFullName())
                    .username(b.getUser().getUsername())
                    .email(b.getUser().getEmail())
                    .kvicRegistrationNumber(b.getKvicRegistrationNumber())
                    .cooperativeName(b.getCooperativeName())
                    .state(b.getState())
                    .district(b.getDistrict())
                    .clusterName(b.getAssignedCluster() != null ? b.getAssignedCluster().getName() : "Unassigned")
                    .hiveCount(hiveCount)
                    .build();
        }).collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<HiveDto> getAllHives() {
        return hiveRepository.findAll().stream().map(h -> HiveDto.builder()
                .id(h.getId())
                .hiveCode(h.getHiveCode())
                .clusterCode(h.getCluster().getClusterCode())
                .clusterName(h.getCluster().getName())
                .beekeeperName(h.getBeekeeper().getUser().getFullName())
                .status(h.getStatus().name())
                .beeSpecies(h.getBeeSpecies())
                .installationDate(h.getInstallationDate())
                .latitude(h.getLatitude())
                .longitude(h.getLongitude())
                .notes(h.getNotes())
                .build()
        ).collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<AuditLogDto> getAuditLogs() {
        return auditLogRepository.findTop50ByOrderByTimestampDesc().stream().map(l -> AuditLogDto.builder()
                .id(l.getId())
                .action(l.getAction())
                .entityName(l.getEntityName())
                .entityId(l.getEntityId())
                .performedBy(l.getPerformedBy())
                .details(l.getDetails())
                .timestamp(l.getTimestamp())
                .build()
        ).collect(Collectors.toList());
    }
}

package com.beeproof.service;

import com.beeproof.domain.Beekeeper;
import com.beeproof.domain.Cluster;
import com.beeproof.domain.Hive;
import com.beeproof.domain.enums.HiveStatus;
import com.beeproof.dto.DomainDtos.BeekeeperOverviewResponse;
import com.beeproof.dto.DomainDtos.HiveDto;
import com.beeproof.exception.ResourceNotFoundException;
import com.beeproof.repository.BeekeeperRepository;
import com.beeproof.repository.HiveRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class BeekeeperService {

    private final BeekeeperRepository beekeeperRepository;
    private final HiveRepository hiveRepository;

    @Transactional(readOnly = true)
    public BeekeeperOverviewResponse getDashboard(String username) {
        Beekeeper beekeeper = beekeeperRepository.findByUserUsername(username)
                .orElseThrow(() -> new ResourceNotFoundException("Beekeeper profile not found for account: " + username));

        Cluster cluster = beekeeper.getAssignedCluster();
        List<Hive> hives = hiveRepository.findByBeekeeper(beekeeper);

        long activeCount = hives.stream().filter(h -> h.getStatus() == HiveStatus.ACTIVE).count();

        List<HiveDto> hiveDtos = hives.stream().map(h -> HiveDto.builder()
                .id(h.getId())
                .hiveCode(h.getHiveCode())
                .clusterCode(h.getCluster().getClusterCode())
                .clusterName(h.getCluster().getName())
                .beekeeperName(beekeeper.getUser().getFullName())
                .status(h.getStatus().name())
                .beeSpecies(h.getBeeSpecies())
                .installationDate(h.getInstallationDate())
                .latitude(h.getLatitude())
                .longitude(h.getLongitude())
                .notes(h.getNotes())
                .build()
        ).collect(Collectors.toList());

        return BeekeeperOverviewResponse.builder()
                .beekeeperId(beekeeper.getId())
                .fullName(beekeeper.getUser().getFullName())
                .kvicRegistrationNumber(beekeeper.getKvicRegistrationNumber())
                .cooperativeName(beekeeper.getCooperativeName())
                .state(beekeeper.getState())
                .district(beekeeper.getDistrict())
                .clusterName(cluster != null ? cluster.getName() : "Unassigned")
                .clusterCode(cluster != null ? cluster.getClusterCode() : "N/A")
                .predominantFlora(cluster != null ? cluster.getPredominantFlora() : "Mixed Wildflower")
                .assignedHiveCount(hives.size())
                .activeHiveCount(activeCount)
                .hives(hiveDtos)
                .build();
    }
}

