import {
  ApiResponse,
  AuthResponse,
  BatchVerificationData,
  AdminOverview,
  BeekeeperDto,
  ClusterDto,
  HiveDto,
  AuditLogDto,
  BeekeeperDashboard,
  User
} from '../types';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8080/api';

class ApiService {
  private getToken(): string | null {
    return localStorage.getItem('beeproof_token');
  }

  private async request<T>(endpoint: string, options: RequestInit = {}): Promise<ApiResponse<T>> {
    const token = this.getToken();
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      ...((options.headers as Record<string, string>) || {}),
    };

    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    try {
      const response = await fetch(`${API_BASE_URL}${endpoint}`, {
        ...options,
        headers,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || `Request failed with status ${response.status}`);
      }

      return data;
    } catch (err: any) {
      // Re-throw with descriptive message
      throw new Error(err.message || 'Network error connecting to BeeProof API');
    }
  }

  // Public Endpoints
  async getHealth() {
    return this.request<any>('/health');
  }

  async verifyBatch(batchNumber: string) {
    return this.request<BatchVerificationData>(`/verify/batch/${encodeURIComponent(batchNumber)}`);
  }

  // Authentication
  async login(credentials: { username: string; password: string }) {
    return this.request<AuthResponse>('/auth/login', {
      method: 'POST',
      body: JSON.stringify(credentials),
    });
  }

  async getCurrentUser() {
    return this.request<User>('/auth/me');
  }

  // Admin / KVIC Endpoints
  async getAdminOverview() {
    return this.request<AdminOverview>('/admin/overview');
  }

  async getAdminBeekeepers() {
    return this.request<BeekeeperDto[]>('/admin/beekeepers');
  }

  async getAdminClusters() {
    return this.request<ClusterDto[]>('/admin/clusters');
  }

  async getAdminHives() {
    return this.request<HiveDto[]>('/admin/hives');
  }

  async getAdminAuditLogs() {
    return this.request<AuditLogDto[]>('/admin/audit-logs');
  }

  // Beekeeper Endpoints
  async getBeekeeperDashboard() {
    return this.request<BeekeeperDashboard>('/beekeeper/dashboard');
  }

  async getBeekeeperHives() {
    return this.request<HiveDto[]>('/beekeeper/hives');
  }

  // Supply Chain Role Endpoints
  async getProcessorOverview() {
    return this.request<any>('/processor/overview');
  }

  async getQualityLabOverview() {
    return this.request<any>('/quality-lab/overview');
  }

  async getDistributorOverview() {
    return this.request<any>('/distributor/overview');
  }
}

export const api = new ApiService();

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { api } from '../services/api';

interface AuthContextType {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (username: string, password: string) => Promise<User>;
  logout: () => void;
  hasRole: (role: UserRole) => boolean;
  getDashboardPathForUser: () => string;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(() => {
    const cachedUser = localStorage.getItem('beeproof_user');
    return cachedUser ? JSON.parse(cachedUser) : null;
  });
  const [token, setToken] = useState<string | null>(() => localStorage.getItem('beeproof_token'));
  const [isLoading, setIsLoading] = useState<boolean>(true);

  useEffect(() => {
    const initializeAuth = async () => {
      const storedToken = localStorage.getItem('beeproof_token');
      if (storedToken) {
        try {
          const res = await api.getCurrentUser();
          if (res.success && res.data) {
            setUser(res.data);
            localStorage.setItem('beeproof_user', JSON.stringify(res.data));
          }
        } catch (err) {
          console.warn('Stored token invalid or expired, clearing session');
          logout();
        }
      }
      setIsLoading(false);
    };

    initializeAuth();
  }, []);

  const login = async (username: string, password: string): Promise<User> => {
    setIsLoading(true);
    try {
      const res = await api.login({ username, password });
      if (res.success && res.data) {
        const receivedToken = res.data.token;
        const loggedUser = res.data.user;

        localStorage.setItem('beeproof_token', receivedToken);
        localStorage.setItem('beeproof_user', JSON.stringify(loggedUser));

        setToken(receivedToken);
        setUser(loggedUser);
        return loggedUser;
      }
      throw new Error(res.message || 'Login failed');
    } finally {
      setIsLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('beeproof_token');
    localStorage.removeItem('beeproof_user');
    setToken(null);
    setUser(null);
  };

  const hasRole = (role: UserRole): boolean => {
    if (!user || !user.roles) return false;
    return user.roles.includes(role);
  };

  const getDashboardPathForUser = (): string => {
    if (!user || !user.roles) return '/';
    if (user.roles.includes('ADMIN_KVIC')) return '/admin';
    if (user.roles.includes('BEEKEEPER')) return '/beekeeper';
    if (user.roles.includes('PROCESSOR')) return '/processor';
    if (user.roles.includes('QUALITY_LAB')) return '/quality-lab';
    if (user.roles.includes('DISTRIBUTOR')) return '/distributor';
    return '/';
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        isAuthenticated: !!token && !!user,
        isLoading,
        login,
        logout,
        hasRole,
        getDashboardPathForUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

