}

export const QrCodeDisplay: React.FC<QrCodeDisplayProps> = ({ url, batchNumber, size = 160 }) => {
  const [copied, setCopied] = useState(false);

  // Encode URL for QR code API (Google Charts / standard SVG QR data fallback)
  const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encodeURIComponent(url)}&color=0D2818&bgcolor=FAF8F5`;

  const handleCopy = () => {
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex flex-col items-center bg-[#FAF8F5] border border-amber-200/80 p-4 rounded-xl shadow-inner">
      <div className="relative p-2 bg-white rounded-lg shadow-sm border border-stone-200">
        <img
          src={qrImageUrl}
          alt={`Provenance QR for Batch ${batchNumber}`}
          className="w-36 h-36 object-contain"
          onError={(e) => {
            // Fallback to SVG placeholder if offline
            (e.target as HTMLElement).style.display = 'none';
          }}
        />
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-10">
          <QrCode className="w-20 h-20 text-[#0D2818]" />
        </div>
      </div>

      <div className="mt-3 text-center">
        <span className="text-[11px] font-mono text-stone-500 uppercase tracking-wider block mb-1">
          Cryptographic Provenance QR
        </span>
        <div className="flex items-center gap-2">
          <button
            onClick={handleCopy}
            className="flex items-center gap-1 text-xs px-2.5 py-1 bg-white hover:bg-stone-50 border border-stone-300 text-stone-700 rounded transition"
            title="Copy verification link"
          >
            {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5 text-stone-500" />}
            <span>{copied ? 'Copied Link' : 'Copy URL'}</span>
          </button>
          <a
            href={url}
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center gap-1 text-xs px-2.5 py-1 bg-amber-600 hover:bg-amber-700 text-white rounded transition"
          >
            <ExternalLink className="w-3.5 h-3.5" />
            <span>Open Link</span>
          </a>
        </div>
      </div>
    </div>
  );
};

