import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { api } from '../services/api';
import { BeekeeperDashboard, BatchResponse, CreateBatchRequest } from '../types';
import { Layers, PlusCircle, ShieldCheck, QrCode, ExternalLink, Check, AlertCircle, X, Sparkles } from 'lucide-react';
import { QrCodeDisplay } from '../components/QrCodeDisplay';

export const BeekeeperPortal: React.FC = () => {
  const { user } = useAuth();
  const [dashboard, setDashboard] = useState<BeekeeperDashboard | null>(null);
  const [batches, setBatches] = useState<BatchResponse[]>([]);
  const [loading, setLoading] = useState(true);

  // Harvest Creation Modal State
  const [isHarvestModalOpen, setIsHarvestModalOpen] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [createdBatch, setCreatedBatch] = useState<BatchResponse | null>(null);

  const [formData, setFormData] = useState<CreateBatchRequest>({
    hiveId: 0,
    quantityKg: 25.0,
    floralSource: '',
    harvestDate: new Date().toISOString().split('T')[0],
    moistureContentPercentage: 17.5,
    notes: 'Pure raw comb harvest logged by beekeeper'
  });

  const fetchData = async () => {
    setLoading(true);
    try {
      const [dashRes, batchRes] = await Promise.all([
        api.getBeekeeperDashboard(),
        api.getBeekeeperBatches()
      ]);
      if (dashRes.success && dashRes.data) {
        setDashboard(dashRes.data);
        if (dashRes.data.hives && dashRes.data.hives.length > 0) {
          setFormData(prev => ({
            ...prev,
            hiveId: dashRes.data.hives[0].id,
            floralSource: dashRes.data.predominantFlora || 'Wild Mangrove'
          }));
        }
      }
      if (batchRes.success && batchRes.data) {
        setBatches(batchRes.data);
      }
    } catch (err) {
      console.error('Failed to load beekeeper data', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleCreateBatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.hiveId) {
      setFormError('Please select a hive.');
      return;
    }
    setSubmitting(true);
    setFormError(null);
    try {
      const res = await api.createBatch(formData);
      if (res.success && res.data) {
        setCreatedBatch(res.data);
        setBatches(prev => [res.data, ...prev]);
      } else {
        setFormError(res.message || 'Failed to create batch');
      }
    } catch (err: any) {
      setFormError(err.message || 'Error communicating with server');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
      {/* Header Profile Card */}
      <div className="p-6 rounded-2xl bg-white border border-sand-200 shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-xl bg-emerald-800 text-white flex items-center justify-center font-bold">
            <Layers className="w-6 h-6" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="font-display text-xl font-bold text-forest-950">
                {dashboard?.fullName || user?.fullName}
              </h1>
              <span className="px-2 py-0.5 text-xs font-semibold rounded bg-emerald-100 text-emerald-900 border border-emerald-300">
                Registered Beekeeper
              </span>
            </div>
            <p className="text-xs text-sand-800 mt-0.5">
              KVIC Registration: <strong className="font-mono text-sand-900">{dashboard?.kvicRegistrationNumber}</strong> • Cooperative: {dashboard?.cooperativeName}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="px-3 py-1.5 rounded-xl bg-sand-100 border border-sand-200 text-xs text-sand-900">
            Assigned Cluster: <strong className="font-semibold text-forest-900">{dashboard?.clusterName}</strong>
          </div>
          <button
            onClick={() => {
              setCreatedBatch(null);
              setIsHarvestModalOpen(true);
            }}
            className="flex items-center gap-2 px-4 py-2 bg-honey-600 hover:bg-honey-700 text-white font-medium text-xs rounded-xl shadow transition"
          >
            <PlusCircle className="w-4 h-4" />
            <span>Log Honey Harvest</span>
          </button>
        </div>
      </div>

      {/* Stats Summary */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="p-5 rounded-2xl bg-white border border-sand-200 space-y-1">
          <span className="text-xs font-semibold text-sand-800 uppercase tracking-wide">Assigned Apiary Hives</span>
          <p className="font-display font-bold text-3xl text-forest-950">{dashboard?.assignedHiveCount ?? 0}</p>
          <p className="text-xs text-emerald-700 font-medium">All hives verified under KVIC cluster registry</p>
        </div>

        <div className="p-5 rounded-2xl bg-white border border-sand-200 space-y-1">
          <span className="text-xs font-semibold text-sand-800 uppercase tracking-wide">Batches Harvested</span>
          <p className="font-display font-bold text-3xl text-forest-950">{batches.length}</p>
          <p className="text-xs text-sand-800">Recorded with real on-chain provenance</p>
        </div>

        <div className="p-5 rounded-2xl bg-white border border-sand-200 space-y-1">
          <span className="text-xs font-semibold text-sand-800 uppercase tracking-wide">Flora Taxonomy</span>
          <p className="font-display font-bold text-base text-honey-700 truncate">{dashboard?.predominantFlora}</p>
          <p className="text-xs text-sand-800">{dashboard?.district}, {dashboard?.state}</p>
        </div>
      </div>

      {/* Harvest Batches Section */}
      <div className="p-6 rounded-2xl bg-white border border-sand-200 space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="font-display font-bold text-base text-forest-950 flex items-center gap-2">
            <ShieldCheck className="w-5 h-5 text-emerald-600" />
            My Harvested Batches ({batches.length})
          </h3>
          <span className="text-xs text-sand-700">Cryptographically Recorded</span>
        </div>

        {batches.length === 0 ? (
          <div className="text-center py-8 bg-sand-50/60 rounded-xl border border-dashed border-sand-300">
            <p className="text-xs text-sand-700">No honey harvest batches logged yet.</p>
            <button
              onClick={() => setIsHarvestModalOpen(true)}
              className="mt-2 text-xs font-bold text-honey-700 underline"
            >
              Log your first harvest batch now
            </button>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead className="bg-sand-100/80 text-sand-800 uppercase font-semibold">
                <tr>
                  <th className="p-3">Batch ID</th>
                  <th className="p-3">Flora</th>
                  <th className="p-3">Harvest Date</th>
                  <th className="p-3">Quantity</th>
                  <th className="p-3">Status</th>
                  <th className="p-3">On-Chain Tx</th>
                  <th className="p-3 text-right">Verification QR</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-sand-100">
                {batches.map((b) => (
                  <tr key={b.id} className="hover:bg-sand-50/70">
                    <td className="p-3 font-mono font-bold text-forest-900">{b.batchNumber}</td>
                    <td className="p-3 text-sand-800">{b.floralSource}</td>
                    <td className="p-3 text-sand-800">{b.harvestDate}</td>
                    <td className="p-3 font-semibold text-sand-900">{b.totalQuantityKg} kg</td>
                    <td className="p-3">
                      <span className="px-2 py-0.5 rounded text-[11px] font-semibold bg-emerald-100 text-emerald-800">
                        {b.status}
                      </span>
                    </td>
                    <td className="p-3 font-mono text-[11px] text-sand-600 max-w-[120px] truncate" title={b.blockchainTxHash}>
                      {b.blockchainTxHash ? b.blockchainTxHash.substring(0, 10) + '...' : 'Recorded'}
                    </td>
                    <td className="p-3 text-right">
                      {b.qrCodeUrl && (
                        <a
                          href={b.qrCodeUrl}
                          target="_blank"
                          rel="noreferrer"
                          className="inline-flex items-center gap-1 text-[11px] font-medium text-honey-700 hover:text-honey-900 underline"
                        >
                          <QrCode className="w-3.5 h-3.5" />
                          <span>View Token</span>
                        </a>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Assigned Hives Table */}
      <div className="p-6 rounded-2xl bg-white border border-sand-200 space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="font-display font-bold text-base text-forest-950">
            Assigned Apiary Hives ({dashboard?.hives?.length ?? 0})
          </h3>
          <span className="text-xs text-sand-800">Cluster: {dashboard?.clusterCode}</span>
        </div>

        {loading ? (
          <p className="text-xs text-sand-800 py-6 text-center">Loading assigned hives...</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead className="bg-sand-100/80 text-sand-800 uppercase font-semibold">
                <tr>
                  <th className="p-3">Hive Code</th>
                  <th className="p-3">Bee Species</th>
                  <th className="p-3">Installation Date</th>
                  <th className="p-3">GPS Coordinates</th>
                  <th className="p-3">Field Notes</th>
                  <th className="p-3">Colony Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-sand-100">
                {dashboard?.hives?.map((h) => (
                  <tr key={h.id} className="hover:bg-sand-50/70">
                    <td className="p-3 font-mono font-bold text-forest-800">{h.hiveCode}</td>
                    <td className="p-3 italic text-sand-800">{h.beeSpecies}</td>
                    <td className="p-3 text-sand-800">{h.installationDate}</td>
                    <td className="p-3 font-mono text-[11px] text-sand-800">
                      {h.latitude ? `${h.latitude.toFixed(4)}, ${h.longitude?.toFixed(4)}` : 'Logged'}
                    </td>
                    <td className="p-3 text-sand-800 max-w-xs truncate">{h.notes || 'Normal hive condition'}</td>
                    <td className="p-3">
                      <span className={`px-2 py-0.5 rounded text-[11px] font-semibold ${
                        h.status === 'ACTIVE' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'
                      }`}>
                        {h.status}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Modal: Create Honey Harvest Batch */}
      {isHarvestModalOpen && (
        <div className="fixed inset-0 z-50 overflow-y-auto bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-[#FAF8F5] w-full max-w-xl rounded-2xl shadow-2xl border border-sand-300 overflow-hidden">
            {/* Modal Header */}
            <div className="bg-forest-900 text-white px-6 py-4 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <PlusCircle className="w-5 h-5 text-honey-400" />
                <h3 className="font-display font-bold text-base text-white">Log Honey Harvest & Mint Provenance</h3>
              </div>
              <button
                onClick={() => setIsHarvestModalOpen(false)}
                className="text-sand-300 hover:text-white p-1 rounded-lg"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {createdBatch ? (
              /* Success Card with Blockchain details & QR Code */
              <div className="p-6 space-y-5">
                <div className="p-4 rounded-xl bg-emerald-50 border border-emerald-300 flex items-center gap-3">
                  <Check className="w-6 h-6 text-emerald-600 shrink-0" />
                  <div>
                    <h4 className="font-bold text-forest-950 text-sm">Harvest Batch Successfully Minted!</h4>
                    <p className="text-xs text-emerald-800">
                      Batch <strong className="font-mono">{createdBatch.batchNumber}</strong> is now registered on-chain with immutable provenance.
                    </p>
                  </div>
                </div>

                <div className="p-4 rounded-xl bg-forest-950 text-sand-200 text-xs font-mono space-y-1.5">
                  <div className="text-honey-400 font-bold uppercase tracking-wider text-[11px]">
                    Blockchain Transaction Proof
                  </div>
                  <div className="truncate"><span className="text-sand-400">Tx Hash: </span>{createdBatch.blockchainTxHash}</div>
                  <div className="truncate"><span className="text-sand-400">Merkle Root: </span>{createdBatch.stateMerkleRoot}</div>
                  <div><span className="text-sand-400">Block Number: </span>#{createdBatch.blockNumber || 1}</div>
                </div>

                {createdBatch.qrCodeUrl && (
                  <div className="flex justify-center">
                    <QrCodeDisplay
                      url={createdBatch.qrCodeUrl}
                      batchNumber={createdBatch.batchNumber}
                      size={150}
                    />
                  </div>
                )}

                <div className="flex justify-end pt-2">
                  <button
                    onClick={() => {
                      setIsHarvestModalOpen(false);
                      setCreatedBatch(null);
                    }}
                    className="px-5 py-2 bg-forest-900 text-white text-xs font-bold rounded-xl"
                  >
                    Done
                  </button>
                </div>
              </div>
            ) : (
              /* Creation Form */
              <form onSubmit={handleCreateBatch} className="p-6 space-y-4 text-xs">
                {formError && (
                  <div className="p-3 bg-red-50 border border-red-200 text-red-700 rounded-xl flex items-center gap-2">
                    <AlertCircle className="w-4 h-4 shrink-0" />
                    <span>{formError}</span>
                  </div>
                )}

                <div>
                  <label className="font-semibold text-sand-800 block mb-1">Select Colony Hive *</label>
                  <select
                    value={formData.hiveId}
                    onChange={(e) => setFormData({ ...formData, hiveId: Number(e.target.value) })}
                    className="w-full p-2.5 rounded-xl border border-sand-300 bg-white text-sand-900"
                    required
                  >
                    {dashboard?.hives?.map((h) => (
                      <option key={h.id} value={h.id}>
                        {h.hiveCode} - {h.beeSpecies} ({h.status})
                      </option>
                    ))}
                  </select>
                  <span className="text-[11px] text-sand-600 mt-0.5 block">
                    Only hives registered to your account can be selected.
                  </span>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="font-semibold text-sand-800 block mb-1">Quantity Harvested (kg) *</label>
                    <input
                      type="number"
                      step="0.5"
                      min="0.5"
                      value={formData.quantityKg}
                      onChange={(e) => setFormData({ ...formData, quantityKg: Number(e.target.value) })}
                      className="w-full p-2.5 rounded-xl border border-sand-300 bg-white text-sand-900 font-mono"
                      required
                    />
                  </div>
                  <div>
                    <label className="font-semibold text-sand-800 block mb-1">Harvest Date *</label>
                    <input
                      type="date"
                      value={formData.harvestDate}
                      onChange={(e) => setFormData({ ...formData, harvestDate: e.target.value })}
                      className="w-full p-2.5 rounded-xl border border-sand-300 bg-white text-sand-900"
                      required
                    />
                  </div>
                </div>

                <div>
                  <label className="font-semibold text-sand-800 block mb-1">Floral Blossom Source *</label>
                  <input
                    type="text"
                    value={formData.floralSource}
                    onChange={(e) => setFormData({ ...formData, floralSource: e.target.value })}
                    placeholder="e.g. Wild Mangrove Khalisha & Goran"
                    className="w-full p-2.5 rounded-xl border border-sand-300 bg-white text-sand-900"
                    required
                  />
                </div>

                <div>
                  <label className="font-semibold text-sand-800 block mb-1">Field Extraction Notes</label>
                  <textarea
                    value={formData.notes}
                    onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                    rows={2}
                    className="w-full p-2.5 rounded-xl border border-sand-300 bg-white text-sand-900"
                  />
                </div>

                <div className="flex justify-end gap-2 pt-2">
                  <button
                    type="button"
                    onClick={() => setIsHarvestModalOpen(false)}
                    className="px-4 py-2 border border-sand-300 rounded-xl text-sand-700 hover:bg-sand-100"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={submitting}
                    className="px-5 py-2 bg-honey-600 hover:bg-honey-700 text-white font-bold rounded-xl disabled:opacity-50"
                  >
                    {submitting ? 'Minting on Blockchain...' : 'Record Harvest Batch'}
                  </button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

