package com.beeproof.config;

import io.swagger.v3.oas.models.Components;
import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.info.Contact;
import io.swagger.v3.oas.models.info.Info;
import io.swagger.v3.oas.models.info.License;
import io.swagger.v3.oas.models.security.SecurityRequirement;
import io.swagger.v3.oas.models.security.SecurityScheme;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class OpenApiConfig {

    @Bean
    public OpenAPI customOpenAPI() {
        final String securitySchemeName = "bearerAuth";
        return new OpenAPI()
                .info(new Info()
                        .title("BeeProof — National Honey Traceability & Apiculture Platform API")
                        .version("1.0.0")
                        .description("Official OpenAPI 3.0 documentation for BeeProof. " +
                                "Covers all 7 phases: Authentication, Batch Provenance & Blockchain Minting, " +
                                "Supply Chain State Transitions (NABL Labs, Processors, Logistics), " +
                                "IoT Telemetry Ingestion & Anomaly Detection, AI Microservice Diagnostics, " +
                                "and KVIC National Oversight Analytics.")
                        .contact(new Contact()
                                .name("BeeProof National Apiculture Mission")
                                .email("contact@beeproof.org")
                                .url("https://beeproof.org"))
                        .license(new License()
                                .name("Apache 2.0")
                                .url("https://www.apache.org/licenses/LICENSE-2.0.html")))
                .addSecurityItem(new SecurityRequirement().addList(securitySchemeName))
                .components(new Components()
                        .addSecuritySchemes(securitySchemeName,
                                new SecurityScheme()
                                        .name(securitySchemeName)
                                        .type(SecurityScheme.Type.HTTP)
                                        .scheme("bearer")
                                        .bearerFormat("JWT")
                                        .description("Enter your JWT token obtained from /api/auth/login")));
    }
}

